with parsed as (select id, plan, currency, tier_prices, discounts, element_at(tier_prices, 1) as entry_price, slice(tier_limits, 1, 2) as first_two_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, array_min(tier_prices) as lowest_price from price_tiers) select currency, case when lowest_price >= 30 then 'LARGE' else 'SMALL' end as lowest_price_tier, count(distinct currency) as distinct_currencies, percentile_approx(entry_price, array(0.25, 0.5, 0.75)) as entry_price_quartiles from parsed group by currency, case when lowest_price >= 30 then 'LARGE' else 'SMALL' end order by distinct_currencies desc
